'use strict';
const modes={lan:{title:'كل الفرق على شبكة واحدة.',copy:'اتصلوا براوتر أو نقطة اتصال هاتف. أرسل عنوان المدير ورمز المسابقة، وابدؤوا دون اشتراك إنترنت.',note:'لا يحتاج التشغيل المحلي إلى خدمة سحابية.'},bt:{title:'اقترن. انضم. ابدأ التحدي.',copy:'اختر البلوتوث، واقترن بجهاز المدير من إعدادات الجهاز، ثم أدخل رمز المسابقة. مناسب للأجهزة المتقاربة التي تدعم RFCOMM.',note:'مدمج في الإصدار الأول؛ توافق الأجهزة يحتاج اختبارًا فعليًا.'},online:{title:'اجمع الفرق من أماكن مختلفة.',copy:'استخدم عنوان خادم ترحيل مشفرًا ورمز المسابقة. مصدر الخادم وتعليمات تشغيله ضمن المشروع على GitHub.',note:'يحتاج إلى إعداد استضافة؛ لا توجد خدمة عامة مستضافة جاهزة.'}};
const tabs=[...document.querySelectorAll('[data-mode]')];function choose(button){tabs.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});const m=modes[button.dataset.mode];document.getElementById('connection-title').textContent=m.title;document.getElementById('connection-copy').textContent=m.copy;document.getElementById('connection-note').textContent=m.note;document.getElementById('connection-detail').setAttribute('aria-labelledby',button.id);}tabs.forEach((b,i)=>{b.addEventListener('click',()=>choose(b));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowLeft'?1:-1)+tabs.length)%tabs.length;choose(tabs[n]);tabs[n].focus();});});choose(tabs[0]);document.getElementById('count-slider').addEventListener('input',e=>document.getElementById('count-preview').textContent=e.target.value);
fetch('release.json').then(r=>r.ok?r.json():null).then(data=>{if(!data)return;for(const [id,key,label]of [['android-download','android','تحميل APK ↙'],['windows-download','windows','تحميل ويندوز المحمول ↙']]){const item=data[key];if(item?.url){const a=document.getElementById(id);a.href=item.url;a.setAttribute('aria-disabled','false');a.textContent=label;a.setAttribute('download',item.filename||'');}}if(data.note)document.getElementById('release-note').textContent=data.note;}).catch(()=>{});
